const e={id:"connect-appflow",track:"amazon-connect",code:"AWS",title:"Amazon AppFlow for Amazon Connect",provider:"Amazon Web Services",level:"Fundamentals",category:"Development",description:"Connectors, connections and flows; on-demand, scheduled and event-triggered runs; permissions; and the service guide for wiring SaaS data into Customer Profiles.",examFormat:"17 topics · ~34 min",sourceFiles:["conne-text/Document 3.txt  (from conne/Document 3.pdf)","conne/Amazon AppFlow.txt"],modules:[{id:"connect-appflow-t1",number:1,title:"What AppFlow actually is (in one sentence)",shortTitle:"What AppFlow actually is (in one sentence)",summary:"It's a managed data-moving service that copies data between SaaS apps (Salesforce, Slack, Zendesk, Marketo, etc.) and AWS services (S3, Redshift,…",duration:"~2 min",lede:null,objectives:[],sections:[{id:"connect-appflow-t1-s1",eyebrow:null,duration:null,title:"Overview",blocks:[{type:"p",text:"It's a managed data-moving service that copies data between SaaS apps (Salesforce, Slack, Zendesk, Marketo, etc.) and AWS services (S3, Redshift, Customer Profiles) — without you writing integration code: Amazon AppFlow is a fully-managed integration service that enables you to securely exchange data between software as a service (SaaS) applications, such as Salesforce, and AWS services, such as Amazon Simple Storage Service (Amazon S3) and Amazon Redshift."},{type:"p",text:'Think of it like a plumber who already has pipes fitted to every brand of sink and every brand of drain — you just tell them "connect this sink to that drain" and they handle the fittings (authentication, API calls, pagination, retries).'}]},{id:"connect-appflow-t1-s2",eyebrow:null,duration:null,title:"The 3 building blocks you need to understand",blocks:[{type:"h",level:4,text:"1. Connector"},{type:"p",text:"A pre-built adapter for a specific app (Salesforce, Zendesk, S3, etc.) that already knows how to talk to that app's API."},{type:"h",level:4,text:"2. Connection"},{type:"p",text:`This is the authenticated link to a specific account of that app. Connections store the configuration details and credentials necessary to run flows without the need to repeatedly enter information. You set this up once (e.g., log into your Salesforce dummy-data org and click "Allow"), and after that, every flow can reuse it — you don't log in again per flow.`},{type:"h",level:4,text:"3. Flow"},{type:"p",text:'This is the actual job definition — "move data from X to Y, mapped this way, on this trigger." A flow uses a connection to transfer data between a source and a destination.'},{type:"p",text:"When you run a flow, Amazon AppFlow verifies that the data is available in the source, processes the data according to the flow configuration, and transfers the processed data to the destination."},{type:"p",text:"Every flow needs 4 things configured:"}]}],reviewQuestions:[]},{id:"connect-appflow-t2",number:2,title:"Source (e.g., Salesforce → Contact object)",shortTitle:"Source (e.g., Salesforce → Contact object)",summary:"Event-triggered — runs automatically the instant something changes in the source. Your event-triggered flow runs when a change occurs to a record…",duration:"~2 min",lede:null,objectives:[],sections:[{id:"connect-appflow-t2-s1",eyebrow:null,duration:null,title:"Overview",blocks:[{type:"h",level:4,text:"Destination (e.g., S3, or in our case Amazon Connect Customer Profiles)"},{type:"ul",items:["Field mapping (which Salesforce field → which destination field)","Trigger (how it fires — see below)"]}]},{id:"connect-appflow-t2-s2",eyebrow:null,duration:null,title:"The 3 ways a flow can run",blocks:[{type:"ul",items:['On demand — you click "Run flow" manually in the console.',"Scheduled — runs on a timer (hourly, daily, etc.) to keep data in sync."]},{type:"p",text:"Event-triggered — runs automatically the instant something changes in the source. Your event-triggered flow runs when a change occurs to a record that you've set up to generate change event notifications — for Salesforce this is powered by Change Data Capture / Platform Events. So if a Salesforce record is edited, AppFlow can react within about a minute."},{type:"p",text:"For your case (dummy data that isn't changing every second), on-demand is the simplest starting point — you control exactly when it pulls from Salesforce."}]},{id:"connect-appflow-t2-s3",eyebrow:null,duration:null,title:`Why it's genuinely useful, not just "another way to call an API"`,blocks:[{type:"p",text:"No code — Create data flows to transfer data between a source and destination in minutes, without writing any code."},{type:"p",text:"Data stays in sync automatically if you schedule/event-trigger it."},{type:"p",text:"Aggregation — Bring your data together — Aggregate data from multiple sources, so you're not stuck with just one CRM feeding one destination."},{type:"p",text:"Security by default — everything is encrypted at rest and in transit, and it can even route traffic privately over AWS's own network instead of the public internet, via AWS PrivateLink integration — meaning your Salesforce data never has to touch the open internet on its way to AWS."},{type:"p",text:'Auditability — every action is logged via AWS CloudTrail integration, so you (or your mentors) can always answer "who ran this flow, and when, and what did it touch."'}]}],reviewQuestions:[]},{id:"connect-appflow-t3",number:3,title:"How permissions work (the boring but important part)",shortTitle:"How permissions work (the boring but importa…",summary:"Before you can do anything, your IAM user/role needs the AmazonAppFlowFullAccess managed policy, plus an S3-specific policy if S3 is involved,…",duration:"~2 min",lede:null,objectives:[],sections:[{id:"connect-appflow-t3-s1",eyebrow:null,duration:null,title:"Overview",blocks:[{type:"p",text:"Before you can do anything, your IAM user/role needs the AmazonAppFlowFullAccess managed policy, plus an S3-specific policy if S3 is involved, since your administrator"},{type:"p",text:'must grant you the permissions required to create and run flows. This is a separate concern from your Salesforce login — IAM controls "can I touch AppFlow at all," while the Salesforce OAuth connection controls "can AppFlow touch my Salesforce data."'}]},{id:"connect-appflow-t3-s2",eyebrow:null,duration:null,title:"The mental model to hold onto for your team explanation",blocks:[{type:"h",level:4,text:"Salesforce (your CRM, source of truth)"},{type:"ul",items:["|","| Connection (one-time OAuth login, reused everywhere) v","Amazon AppFlow ← Flow = source + destination + mapping + trigger |","| Destination v","S3 / Redshift / Amazon Connect Customer Profiles / etc."]},{type:"p",text:"That's the whole concept: connectors are the adapters, a connection is the authenticated pipe to one account, and a flow is a specific, configured job that moves and maps data through that pipe on some trigger."}]}],reviewQuestions:[]},{id:"connect-appflow-t4",number:4,title:"What is Amazon AppFlow?",shortTitle:"What is Amazon AppFlow?",summary:"Amazon AppFlow is a fully-managed integration service that enables you to securely exchange data between software as a service (SaaS)…",duration:"~2 min",lede:null,objectives:[],sections:[{id:"connect-appflow-t4-s1",eyebrow:null,duration:null,title:"Overview",blocks:[{type:"p",text:"Amazon AppFlow is a fully-managed integration service that enables you to securely exchange data between software as a service (SaaS) applications, such as Salesforce, and AWS services, such as Amazon Simple Storage Service (Amazon S3) and Amazon Redshift. For example, you can ingest contact records from Salesforce to Amazon Redshift or pull support tickets from Zendesk to an"},{type:"p",text:"Amazon S3 bucket. The following diagram illustrates how it works:"},{type:"ul",items:["In addition to this User Guide, you can also refer to the","Amazon AppFlow enables you to do the following:"]},{type:"p",text:"Get started quickly — Create data flows to transfer data between a source and destination in minutes, without writing any code."},{type:"p",text:"Keep your data in sync — Run flows on demand or on a schedule to keep data in sync across your SaaS applications and AWS services."},{type:"p",text:"Bring your data together — Aggregate data from multiple sources so that you can train your analytics tools more effectively and save money."},{type:"p",text:"Keep track of your data — Use Amazon AppFlow flow management tools to monitor what data has moved where and when."},{type:"p",text:"Keep your data secure — Security is a top priority. We encrypt your data at rest and in transit."},{type:"p",text:"Transfer data privately — Amazon AppFlow integrates with AWS PrivateLink to provide private data transfer over AWS infrastructure instead of public data transfer over the internet."},{type:"p",text:"Catalog your data for search and discovery — Catalog the data that you transfer to Amazon S3 in the AWS Glue Data Catalog. When you catalog your data, you make it easier to discover and access with AWS analytics and machine learning services."},{type:"p",text:"Organize transferred data into partitions and files — Use partition and aggregation settings to optimize query performance for applications that access the data that you transfer."},{type:"p",text:"Develop custom connectors — Use the Amazon AppFlow Custom Connector SDKs to build connectors for data sources that aren't already integrated with the service. With custom connectors, you can transfer data between private APIs, on-premise systems, other cloud services, and AWS. The SDKs are available on GitHub:"}]}],reviewQuestions:[]},{id:"connect-appflow-t5",number:5,title:"Amazon AppFlow Custom Connector SDK (Python)",shortTitle:"Amazon AppFlow Custom Connector SDK (Python)",summary:"Following are some example uses cases that illustrate the benefits of using Amazon AppFlow.",duration:"~2 min",lede:null,objectives:[],sections:[{id:"connect-appflow-t5-s1",eyebrow:null,duration:null,title:"For a list of Amazon AppFlow Regions, see",blocks:[{type:"p",text:"General Reference."}]},{id:"connect-appflow-t5-s2",eyebrow:null,duration:null,title:"Amazon AppFlow Regions and Endpoints in the AWS",blocks:[{type:"p",text:"Following are some example uses cases that illustrate the benefits of using Amazon AppFlow."}]},{id:"connect-appflow-t5-s3",eyebrow:null,duration:null,title:"Transfer Salesforce opportunities to Amazon Redshift tables",blocks:[{type:"p",text:"Create a flow triggered on each new record created in Salesforce Cloud that calculates the sales potential and then transfers the modified record to an Amazon Redshift table."}]},{id:"connect-appflow-t5-s4",eyebrow:null,duration:null,title:"Analyze Slack conversations",blocks:[{type:"p",text:"Create a flow triggered on a schedule that transfers conversation data from a Slack channel to"},{type:"p",text:"Amazon Redshift, Snowflake, or Amazon S3 for storage and analysis."}]},{id:"connect-appflow-t5-s5",eyebrow:null,duration:null,title:"Transfer support tickets from Zendesk for storage and analysis",blocks:[{type:"p",text:"Create a manually triggered flow for all tickets with a common case number in Zendesk that transfers ticket data to Amazon Redshift, Snowflake, or Amazon S3 for storage and analysis."}]},{id:"connect-appflow-t5-s6",eyebrow:null,duration:null,title:"Transfer aggregate data weekly to S3 at 100GB per flow",blocks:[{type:"p",text:"Create a flow triggered on a weekly schedule to transfer Salesforce, Marketo, ServiceNow, and"},{type:"p",text:"Zendesk data to Amazon S3 in aggregate up to 100GB per flow with low latency."}]},{id:"connect-appflow-t5-s7",eyebrow:null,duration:null,title:"Related AWS services",blocks:[{type:"p",text:"You can use the following services with Amazon AppFlow."}]},{id:"connect-appflow-t5-s8",eyebrow:null,duration:null,title:"AWS CloudTrail",blocks:[{type:"p",text:"Amazon AppFlow is integrated with AWS CloudTrail, a service that provides a record of actions taken by a user, role, or an AWS service in Amazon AppFlow. CloudTrail captures all API calls"},{type:"p",text:"Use cases for Amazon AppFlow as events. The calls captured include calls from the Amazon AppFlow console and code calls to the Amazon AppFlow API operations. If you create a trail, you can enable continuous delivery of CloudTrail events to an Amazon S3 bucket, including events for Amazon"},{type:"p",text:"AppFlow. If you don't configure a trail, you can still view the most recent events in the CloudTrail console in Event history. Using the information collected by CloudTrail, you can determine the request that was made to Amazon AppFlow, the IP address from which the request was made, who made the request, when it was made, and additional details. For more information, see"}]}],reviewQuestions:[]},{id:"connect-appflow-t6",number:6,title:"Logging",shortTitle:"Logging",summary:"Amazon AppFlow API calls with AWS CloudTrail in the Amazon AppFlow User Guide.",duration:"~2 min",lede:null,objectives:[],sections:[{id:"connect-appflow-t6-s1",eyebrow:null,duration:null,title:"Overview",blocks:[{type:"p",text:"Amazon AppFlow API calls with AWS CloudTrail in the Amazon AppFlow User Guide."}]},{id:"connect-appflow-t6-s2",eyebrow:null,duration:null,title:"AWS CloudFormation",blocks:[{type:"p",text:"AWS CloudFormation provides a common language for you to model and provision AWS and third party application resources in your cloud environment. AWS CloudFormation allows you to use programming languages or a simple text file to model and provision, in an automated and secure manner, all the resources needed for your applications across all regions and accounts. This gives you a single source of truth for your AWS and third party resources. Amazon AppFlow supports"},{type:"p",text:"AWS CloudFormation for creating and configuring Amazon AppFlow resources along with the rest of your AWS infrastructure—in a secure, efficient, and repeatable way. For more information, see"},{type:"p",text:"AWS::AppFlow::ConnectorProfile and"},{type:"p",text:"AWS::AppFlow::Flow in the AWS CloudFormation User Guide."}]},{id:"connect-appflow-t6-s3",eyebrow:null,duration:null,title:"Amazon EventBridge",blocks:[{type:"p",text:"Amazon AppFlow integrates with Amazon EventBridge to receive events from Amazon AppFlow sources such as Salesforce. This enables you to publish events ingested by Amazon AppFlow to a partner event bus in Amazon EventBridge. Amazon AppFlow supports the ingestion of Salesforce"},{type:"p",text:"Platform events and Change Data Capture events. You can configure rules in Amazon EventBridge to match patterns from events such as those from Salesforce, and then route them to AWS services such as AWS Lambda, AWS Step Functions, Amazon Simple Queue Service, and others."},{type:"p",text:"You can also use Amazon AppFlow’s private data transfer option to ensure that events don't get exposed to the public internet during transfers between AWS and Salesforce, improving security and minimizing risks of Internet-based attack vectors. For more information, see the"},{type:"p",text:"EventBridge documentation page in the Amazon AppFlow User Guide."}]}],reviewQuestions:[]},{id:"connect-appflow-t7",number:7,title:"AWS Identity and Access Management (IAM)",shortTitle:"AWS Identity and Access Management (IAM)",summary:"IAM is an AWS service that helps an administrator securely control access to AWS resources.",duration:"~2 min",lede:null,objectives:[],sections:[{id:"connect-appflow-t7-s1",eyebrow:null,duration:null,title:"Amazon",blocks:[{type:"p",text:"IAM is an AWS service that helps an administrator securely control access to AWS resources."},{type:"p",text:"Amazon AppFlow integrates with the IAM service so that you can control who in your organization has access to Amazon AppFlow. For more information, see"},{type:"p",text:"AWS Identity and Access Management for Amazon AppFlow in the Amazon AppFlow User Guide."}]},{id:"connect-appflow-t7-s2",eyebrow:null,duration:null,title:"Getting started with Amazon AppFlow",blocks:[{type:"p",text:"This section provides an introduction to Amazon AppFlow with prerequisites for getting started."},{type:"p",text:"The following diagram illustrates how you can use Amazon AppFlow to transfer and enrich data from a data source to a data destination in your flow:"}]},{id:"connect-appflow-t7-s3",eyebrow:null,duration:null,title:"Sign up for an AWS account",blocks:[{type:"p",text:"To get started with AWS, you need an AWS account. For information about creating an AWS account, see"}]},{id:"connect-appflow-t7-s4",eyebrow:null,duration:null,title:"Getting started with an AWS account in the AWS Account Management Reference",blocks:[{type:"p",text:"Guide."},{type:"callout",variant:"note",title:"Prerequisites",body:["Complete the following prerequisites before getting started with Amazon AppFlow.","SaaS application setup — You must verify that you have the required information about the source and destination applications, and that they meet the relevant configuration requirements."]}]},{id:"connect-appflow-t7-s5",eyebrow:null,duration:null,title:"Sign up for an AWS account",blocks:[{type:"p",text:"Supported source and"},{type:"p",text:"For application-specific requirements and setup instructions, see destination applications."},{type:"p",text:"Identity and access management — Your administrator must grant you the permissions required to create and run flows. For more information, see"},{type:"p",text:"Identity and access management for"},{type:"p",text:"Amazon AppFlow."},{type:"p",text:"CloudFormation OAuth (Optional) — If you want to use CloudFormation to create a connector profile for connectors that implement OAuth (such as Salesforce, Slack, Zendesk, and Google"},{type:"p",text:"Analytics), you must fetch the access and refresh tokens. You can do this by implementing your own UI for OAuth, or by retrieving them from elsewhere. Alternatively, you can use the Amazon"},{type:"p",text:"AppFlow console to create the connector profile, and then use that connector profile in the flow creation CloudFormation template."},{type:"p",text:"Data encryption (Optional) — Amazon AppFlow encrypts your data and connection details during transit and at rest. For more information, see"},{type:"p",text:"Data protection in Amazon AppFlow. When you configure a flow, you specify an AWS Key Management Service CMK to use for encryption."},{type:"p",text:"You can choose the AWS managed customer master key (CMK) that Amazon AppFlow creates by default, named AWSDefaultEncryptionKey, or you can choose a customer managed CMK that you create. To create a CMK, see"}]}],reviewQuestions:[]},{id:"connect-appflow-t8",number:8,title:"Creating symmetric CMKs in the AWS Key Management Service",shortTitle:"Creating symmetric CMKs in the AWS Key Manag…",summary:"Developer Guide. For examples of how to set IAM permissions for KMS access, see policy examples for Amazon AppFlow.",duration:"~2 min",lede:null,objectives:[],sections:[{id:"connect-appflow-t8-s1",eyebrow:null,duration:null,title:"Overview",blocks:[{type:"p",text:"Developer Guide. For examples of how to set IAM permissions for KMS access, see policy examples for Amazon AppFlow."}]},{id:"connect-appflow-t8-s2",eyebrow:null,duration:null,title:"Identity-based",blocks:[{type:"callout",variant:"note",title:"Prerequisites",body:["Tutorial: Transfer data between applications with","This tutorial explains how to use Amazon AppFlow with"]}]},{id:"connect-appflow-t8-s3",eyebrow:null,duration:null,title:"Amazon Simple Storage Service (Amazon",blocks:[{type:"p",text:"S3) and Salesforce through the AWS Management Console. Optionally, if you want to use a different supported software as a service (SaaS) application, the tutorial provides general instructions for how to create a flow. A flow uses a connection to transfer data between a source and a destination. When you run a flow, Amazon AppFlow verifies that the data is available in the source, processes the data according to the flow configuration, and transfers the processed data to the destination."}]},{id:"connect-appflow-t8-s4",eyebrow:null,duration:null,title:"Objective",blocks:[{type:"p",text:"In this tutorial, you learn to transfer data between applications. Specifically, you transfer data both from Amazon S3 to Salesforce, and from Salesforce to Amazon S3. First, you synchronize additional account records with the customer relationship management (CRM) data already stored in Salesforce (Flow 1). You can optionally add validations to this flow to only transfer good data."},{type:"p",text:"Then, you transfer the account data in Salesforce to Amazon S3 in an event-triggered flow (Flow 2)."},{type:"p",text:"When Amazon AppFlow detects a change to the target data in the CRM storage service, an event triggered flow runs. This way, you have access to up-to-date information in Amazon S3, where you can import it into an object for data lake hydration to generate business value."},{type:"p",text:"In this tutorial, you accomplish the following:"},{type:"p",text:"Store a sample data set of accounts in"},{type:"h",level:4,text:"Flow 1 — Use"},{type:"p",text:"Amazon Simple Storage Service (Amazon S3)."},{type:"p",text:"Amazon AppFlow to transfer data from Amazon S3 to Salesforce."},{type:"p",text:"Flow 2 — Use Amazon AppFlow to transfer data from Salesforce to Amazon S3."},{type:"p",text:"The following diagram shows the two workflows."},{type:"p",text:"Estimated cost: Some of the actions in this tutorial may incur minor charges on your AWS account. The provided sample data is 1 KB. Should you choose to use your own data, you might incur greater charges. Reduce charges by completing the tutorial through"}]}],reviewQuestions:[]},{id:"connect-appflow-t9",number:9,title:"Step 5: Clean up your resources. For information about pricing, see",shortTitle:"Step 5: Clean up your resources. For informa…",summary:"For information on how to create IAM policies, see Creating IAM policies in the IAM User Guide.",duration:"~2 min",lede:null,objectives:[],sections:[{id:"connect-appflow-t9-s1",eyebrow:null,duration:null,title:"Step 1: Upload data to Amazon S3",blocks:[{type:"p",text:"Amazon S3 pricing and"}]},{id:"connect-appflow-t9-s2",eyebrow:null,duration:null,title:"Step 5: Clean up your resources",blocks:[{type:"p",text:"Amazon AppFlow pricing."}]},{id:"connect-appflow-t9-s3",eyebrow:null,duration:null,title:"Amazon AppFlow User Guide",blocks:[{type:"callout",variant:"note",title:"Prerequisites",body:["Before you begin, you need access to an AWS account and an account for a supported application.","This tutorial uses Salesforce, but you can follow the steps to create flows with a different application. Before you can access the AWS services in this tutorial, your administrator must grant the required permissions to your user, group, or role.","Amazon AppFlow setup — If you haven't already done so, complete the Getting started prerequisites.","AWS Identity and Access Management (IAM) setup — You or your administrator must attach the AWS managed policy AmazonAppFlowFullAccess to your user, group, or role. For information on how to attach an IAM policy, see Adding and removing IAM identity permissions in the IAM User Guide. Also, you must create and attach the following policy to your user, group,","or role."]}]},{id:"connect-appflow-t9-s4",eyebrow:null,duration:null,title:"JSON",blocks:[{type:"p",text:"{"},{type:"p",text:'"Version":"2012-10-17",'}]},{id:"connect-appflow-t9-s5",eyebrow:null,duration:null,title:'"Statement": [',blocks:[{type:"p",text:"{"},{type:"p",text:'"Sid": "VisualEditor0",'},{type:"p",text:'"Effect": "Allow",'}]},{id:"connect-appflow-t9-s6",eyebrow:null,duration:null,title:'"Action": [',blocks:[{type:"p",text:'"s3:GetBucketTagging",'},{type:"p",text:'"s3:ListBucketVersions",'},{type:"p",text:'"s3:CreateBucket",'},{type:"p",text:'"s3:ListBucket",'},{type:"p",text:'"s3:GetBucketPolicy",'},{type:"p",text:'"s3:PutEncryptionConfiguration",'},{type:"p",text:'"s3:GetEncryptionConfiguration",'},{type:"p",text:'"s3:PutBucketTagging",'},{type:"p",text:'"s3:GetObjectTagging",'},{type:"p",text:'"s3:GetBucketOwnershipControls",'},{type:"p",text:'"s3:PutObjectTagging",'},{type:"p",text:'"s3:DeleteObject",'},{type:"p",text:'"s3:DeleteBucket",'},{type:"p",text:'"s3:DeleteObjectTagging",'},{type:"p",text:'"s3:GetBucketPublicAccessBlock",'},{type:"p",text:'"s3:GetBucketPolicyStatus",'},{type:"p",text:'"s3:PutBucketPublicAccessBlock",'}]},{id:"connect-appflow-t9-s7",eyebrow:null,duration:null,title:"Amazon AppFlow User Guide",blocks:[{type:"p",text:'"s3:PutAccountPublicAccessBlock",'},{type:"p",text:'"s3:ListAccessPoints",'},{type:"p",text:'"s3:PutBucketOwnershipControls",'},{type:"p",text:'"s3:PutObjectVersionTagging",'},{type:"p",text:'"s3:DeleteObjectVersionTagging",'},{type:"p",text:'"s3:GetBucketVersioning",'},{type:"p",text:'"s3:GetBucketAcl",'},{type:"p",text:'"s3:PutObject",'},{type:"p",text:'"s3:GetObject",'},{type:"p",text:'"s3:GetAccountPublicAccessBlock",'},{type:"p",text:'"s3:ListAllMyBuckets",'},{type:"p",text:'"s3:GetAnalyticsConfiguration",'}]},{id:"connect-appflow-t9-s8",eyebrow:null,duration:null,title:'"s3:GetBucketLocation"',blocks:[{type:"p",text:"],"}]},{id:"connect-appflow-t9-s9",eyebrow:null,duration:null,title:'"Resource": "*"',blocks:[{type:"p",text:"}"},{type:"p",text:"]"},{type:"p",text:"}"},{type:"p",text:"For information on how to create IAM policies, see Creating IAM policies in the IAM User Guide."},{type:"p",text:"These two policies grant you all the permissions that you need to complete this tutorial. For more information on the different types of policies, see Managed policies and inline policies in the IAM User Guide."},{type:"p",text:"Salesforce setup (Optional) — If you already have a Salesforce account or you want to complete this tutorial with a different SaaS application, you can skip this step. Sign up for a free Salesforce developer account here."}]}],reviewQuestions:[]},{id:"connect-appflow-t10",number:10,title:"Step 1: Upload data to Amazon S3",shortTitle:"Step 1: Upload data to Amazon S3",summary:"Suppose you have data that you want to turn into Salesforce account records. You acquired this data from a web form and used it to generate…",duration:"~2 min",lede:null,objectives:[],sections:[{id:"connect-appflow-t10-s1",eyebrow:null,duration:null,title:"Overview",blocks:[{type:"p",text:"Suppose you have data that you want to turn into Salesforce account records. You acquired this data from a web form and used it to generate account records. You can upload this list of additional accounts to Amazon Simple Storage Service (Amazon S3). Amazon AppFlow can transfer the data from Amazon S3 to Salesforce to synchronize your customer relationship management (CRM) data."},{type:"p",text:"To use Amazon S3 as your source for the flow, create a storage container, called a bucket, and populate it with data. Amazon AppFlow can transfer the data within an S3 bucket to any of the supported destinations. In this step, you create an S3 bucket, create a source folder within the S3 bucket, and upload sample data to the source folder."}]},{id:"connect-appflow-t10-s2",eyebrow:null,duration:null,title:"Additional resources (Optional) Download sample data",blocks:[{type:"p",text:"If you have your own data that you want to use for this tutorial, you can skip this step. Also, if you use a SaaS application other than Salesforce, this sample data may not be useful."},{type:"p",text:"The sample data includes nine account records. Download this sample data set."}]},{id:"connect-appflow-t10-s3",eyebrow:null,duration:null,title:"To get the sample data",blocks:[{type:"p",text:"1. Download the zip file tutorial-account-data.zip."},{type:"p",text:"2. Extract the zip file. The unzipped file called tutorial-account-data.csv contains the sample data set."}]},{id:"connect-appflow-t10-s4",eyebrow:null,duration:null,title:"Create an S3 bucket",blocks:[{type:"p",text:"After you extract your sample data, use the AWS Management Console to create an S3 bucket to store your data. Your S3 bucket must occupy the same AWS Region as the one where you want to use Amazon AppFlow."}]}],reviewQuestions:[]},{id:"connect-appflow-t11",number:11,title:"To create an S3 bucket",shortTitle:"To create an S3 bucket",summary:"1. Open the Amazon S3 console at https://console.aws.amazon.com/s3/.",duration:"~2 min",lede:null,objectives:[],sections:[{id:"connect-appflow-t11-s1",eyebrow:null,duration:null,title:"Overview",blocks:[{type:"p",text:"1. Open the Amazon S3 console at https://console.aws.amazon.com/s3/."},{type:"p",text:"2. In the Buckets section, choose Create bucket."},{type:"p",text:"3. For Bucket name, enter a descriptive name. The name must be globally unique. For example,"},{type:"p",text:"enter username-appflow-tutorial."},{type:"p",text:"4. For AWS Region, choose the same Region as your Amazon AppFlow console."}]},{id:"connect-appflow-t11-s2",eyebrow:null,duration:null,title:"(Optional) Download sample data",blocks:[{type:"callout",variant:"warning",title:"Warning",body:["If your S3 bucket isn't in the same AWS Region as your console, your flow can't access it.","5. Keep the other settings at their default values. Choose Create bucket."]}]},{id:"connect-appflow-t11-s3",eyebrow:null,duration:null,title:"Create a folder in an S3 bucket",blocks:[{type:"p",text:"Now that you have an S3 bucket, use the console to create a folder in the bucket where you want to store the sample data. While a folder isn't essential, it's useful for keeping your files organized."}]},{id:"connect-appflow-t11-s4",eyebrow:null,duration:null,title:"To create a folder in Amazon S3",blocks:[{type:"p",text:"1. Open the Amazon S3 console at https://console.aws.amazon.com/s3/."},{type:"p",text:"2. In the Buckets section, choose your S3 bucket from the list."},{type:"p",text:"3. Under the Objects tab, choose Create folder."},{type:"p",text:"4. For the folder name, enter source."},{type:"p",text:"5. Choose Create folder."}]},{id:"connect-appflow-t11-s5",eyebrow:null,duration:null,title:"Upload data to Amazon S3",blocks:[{type:"p",text:"Now that you have set up your S3 bucket, upload the data."}]},{id:"connect-appflow-t11-s6",eyebrow:null,duration:null,title:"To populate the S3 bucket with data",blocks:[{type:"p",text:"1. Open the Amazon S3 console at https://console.aws.amazon.com/s3/."},{type:"p",text:"2. In the Buckets section, choose your S3 bucket from the list."},{type:"p",text:"3. Choose the source folder. Then, under the Objects tab, choose Upload."},{type:"p",text:"4. Choose Add files, and choose your data set. If you downloaded the sample data set, choose the tutorial-account-data.csv file."},{type:"p",text:"5. Choose Upload."},{type:"p",text:"You now have an S3 bucket with sample data in the source folder."}]}],reviewQuestions:[]},{id:"connect-appflow-t12",number:12,title:"Create a folder",shortTitle:"Create a folder",summary:"For more information on Amazon S3, see the following resources:",duration:"~2 min",lede:null,objectives:[],sections:[{id:"connect-appflow-t12-s1",eyebrow:null,duration:null,title:"Additional resources",blocks:[{type:"p",text:"For more information on Amazon S3, see the following resources:"},{type:"ul",items:["Amazon S3 in the Amazon AppFlow User Guide.","Amazon S3 in the Amazon S3 User Guide."]}]},{id:"connect-appflow-t12-s2",eyebrow:null,duration:null,title:"Step 2: Connect Amazon AppFlow to an application",blocks:[{type:"p",text:"You can securely move your data between supported source and destination applications with a connection in Amazon AppFlow. Connections store the configuration details and credentials necessary to run flows without the need to repeatedly enter information. After you have an established connection with an application, you can use that connection in new or existing flows."}]},{id:"connect-appflow-t12-s3",eyebrow:null,duration:null,title:"Additional resources",blocks:[{type:"callout",variant:"note",title:"Prerequisites",body:["Before you begin, complete the tutorial prerequisites."]}]},{id:"connect-appflow-t12-s4",eyebrow:null,duration:null,title:"Create a connection between Amazon AppFlow and a SaaS application",blocks:[{type:"p",text:"If you want to create and run a flow, you must establish a connection with the software as a service (SaaS). You can create this connection while you create the flow, or you can create the connection separately. Here, you create a connection in Amazon AppFlow before you create the flow."}]},{id:"connect-appflow-t12-s5",eyebrow:null,duration:null,title:"To create a connection with Salesforce",blocks:[{type:"p",text:"1. Open the Amazon AppFlow console at https://console.aws.amazon.com/appflow/."},{type:"p",text:"2. Expand the navigation pane on the left-hand side of the console page and choose"},{type:"p",text:"Connections."},{type:"p",text:"3. For Connectors, select Salesforce."},{type:"p",text:"4. Choose Create connection."}]},{id:"connect-appflow-t12-s6",eyebrow:null,duration:null,title:"Additional resources",blocks:[{type:"p",text:"5. Leave the default selections and enter a Connection name. For example, enter my salesforce-connection."},{type:"p",text:"6. Choose Continue."},{type:"p",text:"7. If you're not already logged into Salesforce, Amazon AppFlow prompts you to log in."},{type:"p",text:"8. Choose Allow to give Amazon AppFlow access to your Salesforce account."}]}],reviewQuestions:[]},{id:"connect-appflow-t13",number:13,title:"To create a connection with other applications",shortTitle:"To create a connection with other applications",summary:"Supported applications page and select the application that you want to connect with. Follow the instructions for your selected application.",duration:"~2 min",lede:null,objectives:[],sections:[{id:"connect-appflow-t13-s1",eyebrow:null,duration:null,title:"Overview",blocks:[{type:"p",text:"Go to the"},{type:"p",text:"Supported applications page and select the application that you want to connect with. Follow the instructions for your selected application."},{type:"p",text:"You now have a connection in the Amazon AppFlow console to your SaaS account. If you use the same third-party application in both flows, you only need one connection."}]},{id:"connect-appflow-t13-s2",eyebrow:null,duration:null,title:"Additional resources",blocks:[{type:"p",text:"For more information on connections, see the following resources:"},{type:"ul",items:["Managing connections in the Amazon AppFlow User Guide.","Salesforce in the Amazon AppFlow User Guide."]}]},{id:"connect-appflow-t13-s3",eyebrow:null,duration:null,title:"Step 3: Transfer data from Amazon S3 to a SaaS destination",blocks:[{type:"p",text:"Amazon S3 now hosts your data, but you still need to synchronize all your records in the destination. To transfer data to a supported destination, you must create and run a flow with"},{type:"p",text:"Amazon AppFlow. In this step, you use the AWS Management Console to send data from Amazon"},{type:"p",text:"S3 to either Salesforce or another software as a service (SaaS) application."}]},{id:"connect-appflow-t13-s4",eyebrow:null,duration:null,title:"Create a flow",blocks:[{type:"p",text:"Step 1: Upload data to Amazon S3."},{type:"p",text:"The following procedures detail how to create a flow from Amazon S3 to Salesforce, but you can follow the steps with any destination."}]},{id:"connect-appflow-t13-s5",eyebrow:null,duration:null,title:"To complete Step 1: Specify flow details",blocks:[{type:"p",text:"1. Open the Amazon AppFlow console at https://console.aws.amazon.com/appflow/. Ensure the"},{type:"p",text:"AWS Region of your Amazon AppFlow console is the same one as your S3 bucket."},{type:"p",text:"2. Choose Create flow."},{type:"p",text:"3. For Flow name, enter s3-to-SaaS. For example, if your destination is Salesforce, enter s3 to-salesforce."},{type:"p",text:"4. Under Data encryption, you have the option to activate custom encryption settings. By default, Amazon AppFlow encrypts your data with a key in AWS Key Management Service (AWS KMS). AWS creates, uses, and manages this key for you. Amazon AppFlow always encrypts your data during transit and at rest. The default encryption is adequate for this tutorial, so don't select custom encryption settings. For more information, see in the Amazon AppFlow User Guide."}]}],reviewQuestions:[]},{id:"connect-appflow-t14",number:14,title:"Data protection",shortTitle:"Data protection",summary:"5. Under Tags, you have the option to add tags to your flow. Tags are key-value pairs that assign metadata to resources that you create. Tags are…",duration:"~2 min",lede:null,objectives:[],sections:[{id:"connect-appflow-t14-s1",eyebrow:null,duration:null,title:"Overview",blocks:[{type:"p",text:"5. Under Tags, you have the option to add tags to your flow. Tags are key-value pairs that assign metadata to resources that you create. Tags are not necessary for this tutorial. For more information, see"},{type:"p",text:"Tagging AWS resources in the AWS General Reference."},{type:"p",text:"6. To continue to Step 2: Configure flow, choose Next."}]},{id:"connect-appflow-t14-s2",eyebrow:null,duration:null,title:"To complete Step 2: Configure flow",blocks:[{type:"p",text:"1. For Source name, choose Amazon S3."},{type:"p",text:"2. In Bucket details, for Choose an S3 bucket, select your S3 bucket."},{type:"p",text:"3. For Enter bucket prefix, enter source. Bucket prefixes are folders."},{type:"p",text:"4. Ensure Data format preference is CSV format."},{type:"p",text:"5. Configure the Destination details. These details vary based on the destination that you want to transfer data to."},{type:"p",text:"If you want to transfer data to Salesforce, do the following:"},{type:"callout",variant:"note",title:"Prerequisites",body:["For Destination name, select Salesforce.","a.","b. For Choose Salesforce connection, select your connection. For example, select my salesforce-connection, the connection that you created in the previous step."]}]},{id:"connect-appflow-t14-s3",eyebrow:null,duration:null,title:"Tip",blocks:[{type:"p",text:"If you don't have a connection, you can choose Connect to create one now."},{type:"p",text:"c."},{type:"p",text:"If you want to use the sample data that you downloaded, for Choose Salesforce object, select Account."},{type:"p",text:"If you want to transfer data to another supported application besides Salesforce, do the following:"},{type:"ul",items:["a.","For Destination name, select the destination that you want for your data.","b. For Choose connection, select the connection that you created, or create one.","c.","Select object and specify the correct object type for your data.","d. If there are any other destination details, configure the required fields."]},{type:"p",text:"6. In the Error handling section, you can specify how you want the flow to handle errors and where to put the data that causes errors. For this tutorial, you can leave the settings in this section at their default values."},{type:"p",text:"7. For Flow trigger, leave the default selection Run on demand. When you select this value, you use a single button in the console to run the flow."}]}],reviewQuestions:[]},{id:"connect-appflow-t15",number:15,title:"Tip",shortTitle:"Tip",summary:"You can also run flows on a schedule. Amazon AppFlow bases the time zone for this schedule on your web browser. For more information, see",duration:"~2 min",lede:null,objectives:[],sections:[{id:"connect-appflow-t15-s1",eyebrow:null,duration:null,title:"Overview",blocks:[{type:"p",text:"You can also run flows on a schedule. Amazon AppFlow bases the time zone for this schedule on your web browser. For more information, see"},{type:"p",text:"Schedule-triggered flows in the Amazon AppFlow User Guide."},{type:"p",text:"8. To continue to Step 3: Map data fields, choose Next."}]},{id:"connect-appflow-t15-s2",eyebrow:null,duration:null,title:"To complete Step 3: Map data fields",blocks:[{type:"p",text:"1. Map your data fields. These vary based on the destination for your data transfer."},{type:"p",text:"If you're transferring to Salesforce, do the following:"}]},{id:"connect-appflow-t15-s3",eyebrow:null,duration:null,title:"Create a flow",blocks:[{type:"p",text:"Under Mapping method, leave the default selection Manually map fields."},{type:"p",text:"a."},{type:"p",text:"b. Under Destination record preference, leave the default selection Insert new records."},{type:"p",text:"c."},{type:"p",text:"In the Source to destination field mapping section, select the Choose source fields dropdown and select Map all fields directly."},{type:"callout",variant:"warning",title:"Important",body:["If you use the sample data, ensure Account Name maps to Account Name,"]}]},{id:"connect-appflow-t15-s4",eyebrow:null,duration:null,title:"Account Type maps to Account Type, Billing State/Province maps to Billing",blocks:[{type:"p",text:"State/Province, Account Rating maps to Account Rating, and Industry maps to"},{type:"p",text:"Industry."},{type:"p",text:"d. Choose Map selected fields."},{type:"p",text:"If you want to transfer data to another supported application besides Salesforce, do the following:"},{type:"p",text:"a."},{type:"p",text:"Select Mapping method and specify how you want to map your data. You can choose to map the source fields to the destination fields manually, or else upload a .csv file that includes these mappings."},{type:"p",text:"b. Map your fields from the source field name to the destination field name."},{type:"p",text:"2. Under Validations, specify what happens to invalid data within the flow. For this step, you don't need any validations."},{type:"p",text:"3. To continue to Step 4: Add filters, choose Next."}]},{id:"connect-appflow-t15-s5",eyebrow:null,duration:null,title:"To complete Step 4: Add filters",blocks:[{type:"p",text:"1. Under Filters, specify what data the flow transfers. With this setting, you can ensure the flow transfers data only when it meets certain criteria. For this tutorial, you don't need any filters."},{type:"p",text:"2. To continue to Step 5: Review and create, choose Next."}]}],reviewQuestions:[]},{id:"connect-appflow-t16",number:16,title:"To complete Step 5: Review and create",shortTitle:"To complete Step 5: Review and create",summary:"Review the flow settings, and then choose Create flow.",duration:"~2 min",lede:null,objectives:[],sections:[{id:"connect-appflow-t16-s1",eyebrow:null,duration:null,title:"Overview",blocks:[{type:"p",text:"Review the flow settings, and then choose Create flow."}]},{id:"connect-appflow-t16-s2",eyebrow:null,duration:null,title:"Run a flow",blocks:[{type:"p",text:"You now have a run-on-demand flow. When you choose the Run flow button in the console, this flow transfers your data."}]},{id:"connect-appflow-t16-s3",eyebrow:null,duration:null,title:"To run a flow",blocks:[{type:"p",text:"1. In Flows, select your flow from the list."},{type:"p",text:"2. Choose Run flow."},{type:"p",text:"When the flow successfully runs, a banner appears. If you use the provided data, the banner shows nine processed records."}]},{id:"connect-appflow-t16-s4",eyebrow:null,duration:null,title:"View transferred data",blocks:[{type:"p",text:"After your flow runs, you can view the data in the destination."}]},{id:"connect-appflow-t16-s5",eyebrow:null,duration:null,title:"To view transferred data",blocks:[{type:"p",text:"If you use the sample Salesforce account data, navigate to your Salesforce Account tab to view the imported account records. For more information on Salesforce accounts, see accounts."}]},{id:"connect-appflow-t16-s6",eyebrow:null,duration:null,title:"Salesforce",blocks:[{type:"p",text:"You have now transferred data from Amazon S3 to Salesforce or the SaaS application that you chose. If you used Salesforce and the sample data, you have synchronized and expanded your"},{type:"p",text:"Salesforce account data."}]},{id:"connect-appflow-t16-s7",eyebrow:null,duration:null,title:"(Optional) Edit flow to add validations",blocks:[{type:"p",text:"The flow that you ran transferred all the records in the data set. You can add validations to a flow so that you transfer only valid records. In this procedure, if you use the sample data, you edit your"},{type:"p",text:"Amazon S3 to Salesforce flow to transfer only account records with ratings."}]},{id:"connect-appflow-t16-s8",eyebrow:null,duration:null,title:"Run a flow",blocks:[{type:"p",text:"Before you edit and run the flow again, delete the records that you transferred from the original flow."}]},{id:"connect-appflow-t16-s9",eyebrow:null,duration:null,title:"To delete account records in Salesforce",blocks:[{type:"p",text:"Follow the directions in"},{type:"p",text:"Mass Delete Records."},{type:"p",text:"For the sample data set, suppose you consider account records valid only if they have an account rating. Two of the account records don't have associated account ratings. You don't want these records to transfer from Amazon S3 so that you only have valid data in Salesforce."}]}],reviewQuestions:[]},{id:"connect-appflow-t17",number:17,title:"To edit a flow and add validations",shortTitle:"To edit a flow and add validations",summary:"https://console.aws.amazon.com/appflow/.",duration:"~11 min",lede:null,objectives:[],sections:[{id:"connect-appflow-t17-s1",eyebrow:null,duration:null,title:"Overview",blocks:[{type:"p",text:"1. Open the Amazon AppFlow console at"},{type:"p",text:"2. In Flows, choose your flow."},{type:"p",text:"https://console.aws.amazon.com/appflow/."},{type:"p",text:"3. Choose Actions, then choose Edit flow."},{type:"p",text:"4. Choose Next until you reach Step 3: Edit data fields."},{type:"p",text:"5. In Validations, choose Add validation."},{type:"p",text:"6. If you use the sample data, for Field name, select Account rating. For Condition, choose"},{type:"p",text:"Values missing or null. For Action, choose Ignore record. This configuration will omit the transfer of account records with missing rating values."},{type:"p",text:"7. Choose Save."}]},{id:"connect-appflow-t17-s2",eyebrow:null,duration:null,title:"To run the edited flow and view transferred data",blocks:[{type:"p",text:"1. In Flows, select your flow from the list."},{type:"p",text:"2. Choose Run flow. When the flow successfully runs, a banner appears."}]},{id:"connect-appflow-t17-s3",eyebrow:null,duration:null,title:"(Optional) Edit flow to add validations",blocks:[{type:"p",text:"3. If you use the sample Salesforce account data, navigate to your Salesforce Account tab to view the imported account records. For more information on Salesforce accounts, see"}]},{id:"connect-appflow-t17-s4",eyebrow:null,duration:null,title:"Salesforce",blocks:[{type:"p",text:"Accounts."},{type:"p",text:"If you used the sample data, only seven of the nine records transferred. Example4 and Example8 do not appear because they have no account ratings associated with them."}]},{id:"connect-appflow-t17-s5",eyebrow:null,duration:null,title:"Step 4: Transfer data from a SaaS source to Amazon S3",blocks:[{type:"p",text:"Suppose you now want to transfer your data from Salesforce to Amazon S3. With Amazon S3, you can synchronize and replicate customer relationship management (CRM) data into data lakes to analyze or use to drive machine learning. To keep this information up to date, you can create an event-triggered flow from Salesforce to Amazon S3. An event-triggered flow runs when Amazon"},{type:"p",text:"AppFlow detects a change to the target data in the CRM storage service."},{type:"p",text:"After you create an S3 bucket, you can set up and run a flow with Amazon AppFlow to transfer data from a supported source to the S3 bucket. You can use one S3 bucket as both a source and destination, so you don't need to create a new S3 bucket if you already created one for this tutorial."},{type:"p",text:"In this step, you use the AWS Management Console to create and run a flow from Salesforce or another software as a service (SaaS) application to Amazon S3."}]},{id:"connect-appflow-t17-s6",eyebrow:null,duration:null,title:"Step 4: Transfer data from a SaaS source to Amazon S3",blocks:[{type:"callout",variant:"note",title:"Prerequisites",body:["Before you begin, you need an S3 bucket to receive the data if you don't already have one. You can use the same S3 bucket as both a source and destination for different flows. This tutorial uses","Salesforce for a SaaS account, but you can use another supported source application if you want.","Some flow options that this tutorial uses don't work for a SaaS application other than Salesforce.","Amazon S3 setup — If you don't already have an S3 bucket,","Amazon S3 to receive your data."]}]},{id:"connect-appflow-t17-s7",eyebrow:null,duration:null,title:"Create an S3 bucket to prepare",blocks:[{type:"p",text:"Salesforce setup (Optional) — If you already have a Salesforce account, or you want to complete this tutorial with a different SaaS application, you can skip this step. Sign up for a free"},{type:"p",text:"Salesforce developer account here."},{type:"p",text:"Transfer data to Salesforce (Optional) — If you use Salesforce for this tutorial, we recommend that you complete"},{type:"p",text:"Step 3: Transfer data from Amazon S3 before you continue."}]},{id:"connect-appflow-t17-s8",eyebrow:null,duration:null,title:"Change data capture in Salesforce",blocks:[{type:"p",text:"To run an event-triggered flow, Amazon AppFlow needs to receive a notification when a record changes. When you use the change data capture feature in Salesforce, you can generate change event notifications for selected entities. If you don't have administrator-level credentials, you might not be able to select entities to generate change notifications. However, the free developer account has administrator privileges."}]},{id:"connect-appflow-t17-s9",eyebrow:null,duration:null,title:"To enable change data capture",blocks:[{type:"p",text:"1. Open Salesforce at www.salesforce.com and log in to your account."},{type:"p",text:"2. Navigate to the Change Data Capture page."},{type:"p",text:"3. If you use the sample data, select Account (Account) to generate change event notifications."},{type:"p",text:"Otherwise, select the appropriate entity for your data."}]},{id:"connect-appflow-t17-s10",eyebrow:null,duration:null,title:"Create a flow",blocks:[{type:"p",text:"Change Data Capture."},{type:"p",text:"The following procedures detail how to create a flow from Salesforce to Amazon S3, but you can follow the steps with any supported source. Some flow options that this tutorial uses don't work for a SaaS application other than Salesforce, but alternate steps appear."},{type:"p",text:"Prerequisites https://console.aws.amazon.com/appflow/."}]},{id:"connect-appflow-t17-s11",eyebrow:null,duration:null,title:"To complete Step 1: Specify flow details",blocks:[{type:"p",text:"1. Open the Amazon AppFlow console at"},{type:"p",text:"2. Choose Create flow."},{type:"p",text:"3. For Flow name, enter SaaS-to-s3. For example, if your source is Salesforce, enter salesforce-to-s3."},{type:"p",text:"4. Under Data encryption, you have the option to activate custom encryption settings. By default, Amazon AppFlow encrypts your data with a key in AWS Key Management Service (AWS KMS). AWS creates, uses, and manages this key for you. Amazon AppFlow always encrypts your data during transit and at rest. The default encryption is adequate for this tutorial, so don't select custom encryption settings. For more information, see"},{type:"p",text:"Data protection in the Amazon AppFlow User Guide."},{type:"p",text:"5. Under Tags, you have the option to add tags to your flow. Tags are key-value pairs that assign metadata to resources that you create. Tags aren't necessary for this tutorial. For more information, see"},{type:"p",text:"Tagging AWS resources in the AWS General Reference."},{type:"p",text:"6. To continue to Step 2: Configure flow, choose Next."}]},{id:"connect-appflow-t17-s12",eyebrow:null,duration:null,title:"To complete Step 2: Configure flow",blocks:[{type:"p",text:"1. Configure the Source details. These details vary based on the source that you want to transfer data from."},{type:"p",text:"If you want to transfer data from Salesforce, do the following:"},{type:"ul",items:["a.","For Source name, choose Salesforce."]},{type:"p",text:"b. For Choose Salesforce connection, select your connection. For example, select my salesforce-connection, the connection that you created in a previous step."},{type:"callout",variant:"key",title:"Tip",body:["If you don't have a connection, you can choose Connect to create one now.","c.","Select Salesforce events.","d. If you use the sample data, for Choose Salesforce event, select Account Change","Event. Otherwise, select the event that matches your data.","If you want to transfer data from another supported application besides Salesforce, do the following:"]}]},{id:"connect-appflow-t17-s13",eyebrow:null,duration:null,title:"Create a flow",blocks:[{type:"p",text:"For Source name, select the source that you want for your data."},{type:"p",text:"a."},{type:"p",text:"b. For Choose connection, select the connection that you created, or create one."},{type:"p",text:"c."},{type:"p",text:"Select object and specify the correct object type for your data."},{type:"p",text:"d. If there are any other source details, configure the required fields."},{type:"p",text:"2. For Destination name, choose Amazon S3."},{type:"p",text:"3. In Bucket details, for Choose an S3 bucket, select your S3 bucket. Use the same S3 bucket that contains the source folder from the previous step."},{type:"p",text:"4. For Enter bucket prefix, enter destination. Bucket prefixes are folders."},{type:"callout",variant:"key",title:"Tip",body:["If you don't have a folder that matches the name that you entered, the flow automatically creates one when it runs.","5. Configure the Flow trigger. This varies based on the source where you want to transfer data from.","If you want to transfer data from Salesforce, leave the default selection Run flow on event.","If you want to transfer data from another supported application besides Salesforce, leave the default selection Run on demand. This option allows you to run the flow with the selection of one button in the console."]},{type:"callout",variant:"key",title:"Tip",body:["You can also run flows on a schedule. Amazon AppFlow bases the time zone for this schedule on your web browser. For more information, see flows in the Amazon AppFlow User Guide.","6. To continue to Step 3: Map data fields, choose Next."]}]},{id:"connect-appflow-t17-s14",eyebrow:null,duration:null,title:"Schedule-triggered",blocks:[{type:"p",text:"1. Under Mapping method, leave the default selection Manually map fields."},{type:"p",text:"2. In the Source to destination field mapping section, select the Choose source fields dropdown and select Map all fields directly."}]},{id:"connect-appflow-t17-s15",eyebrow:null,duration:null,title:"Create a flow",blocks:[{type:"p",text:"3. Under Validations, specify what happens to invalid data within the flow. For this step, you don't need any validations."},{type:"p",text:"4. To continue to Step 4: Add filters, choose Next."}]},{id:"connect-appflow-t17-s16",eyebrow:null,duration:null,title:"To complete Step 4: Add filters",blocks:[{type:"p",text:"1. Under Filters, specify what data the flow transfers. With this setting, you can ensure the flow transfers data only when it meets certain criteria. For this tutorial, you don't need any filters."},{type:"p",text:"2. To continue to Step 5: Review and create, choose Next."}]},{id:"connect-appflow-t17-s17",eyebrow:null,duration:null,title:"To complete Step 5: Review and create",blocks:[{type:"p",text:"Review the flow settings, then choose Create flow."}]},{id:"connect-appflow-t17-s18",eyebrow:null,duration:null,title:"Run a flow",blocks:[{type:"p",text:"You now have a flow. The source that you use determines how you run this flow."}]},{id:"connect-appflow-t17-s19",eyebrow:null,duration:null,title:"Run an event-triggered flow with Salesforce",blocks:[{type:"p",text:"Your event-triggered flow runs when a change occurs to a record that you've set up to generate change event notifications. Here, you change a record within your Salesforce account to activate a flow run."}]},{id:"connect-appflow-t17-s20",eyebrow:null,duration:null,title:"To run an event-triggered flow with Salesforce",blocks:[{type:"p",text:"1. Open the Amazon AppFlow console at https://console.aws.amazon.com/appflow/."},{type:"p",text:"2. In Flows, select the salesforce-to-s3 flow."},{type:"p",text:"3. Choose Activate flow."},{type:"p",text:"4. Open Salesforce at www.salesforce.com and log in to your account."},{type:"p",text:"5. Navigate to the page where Salesforce stores your records. For the sample data, this is the"},{type:"p",text:"Accounts page."},{type:"p",text:"6. Edit one of the records. For example, in the sample data, change the Rating in Example3 from cold to hot."}]},{id:"connect-appflow-t17-s21",eyebrow:null,duration:null,title:"Run a flow (event-triggered or on-demand)",blocks:[{type:"p",text:"After about a minute, refresh your flow page in Amazon AppFlow. When the flow successfully runs,"},{type:"p",text:"a timestamp from the last flow run appears."}]},{id:"connect-appflow-t17-s22",eyebrow:null,duration:null,title:"Run an on-demand flow with a supported SaaS source",blocks:[{type:"p",text:"Your on-demand flow runs when you choose the Run flow button in the console."}]},{id:"connect-appflow-t17-s23",eyebrow:null,duration:null,title:"To run an on-demand flow",blocks:[{type:"p",text:"1. In Flows, select your flow from the list."},{type:"p",text:"2. Choose Run flow."},{type:"p",text:"When the flow successfully runs, a banner appears."}]},{id:"connect-appflow-t17-s24",eyebrow:null,duration:null,title:"View transferred data",blocks:[{type:"p",text:"The data from your source now resides in your S3 bucket. From the S3 bucket, you can, for example, consume the data from multiple AWS services for analysis. In this step, you download and view the data on your computer."}]},{id:"connect-appflow-t17-s25",eyebrow:null,duration:null,title:"To retrieve the transferred data",blocks:[{type:"p",text:"1. Open the Amazon S3 console at https://console.aws.amazon.com/s3/."},{type:"p",text:"2. In Buckets, choose your S3 bucket from the list."},{type:"p",text:"3. In your S3 bucket, choose the destination folder. Then choose the flow folder, for example,"},{type:"p",text:"salesforce-to-s3."},{type:"p",text:"4. The folder contains one file. Select this file and choose Download."},{type:"p",text:"5. Navigate to the file in your Downloads folder and rename it with a descriptive name."}]},{id:"connect-appflow-t17-s26",eyebrow:null,duration:null,title:"View transferred data",blocks:[{type:"p",text:"6. Open the file to view the updated record."},{type:"p",text:"You've now transferred data from Salesforce or the SaaS that you chose to Amazon S3. If you used"},{type:"p",text:"Salesforce, you set up an event-triggered flow to keep up-to-date with changing data."}]},{id:"connect-appflow-t17-s27",eyebrow:null,duration:null,title:"Step 5: Clean up your resources",blocks:[{type:"p",text:"After you've completed the tutorial, it's good practice to clean up any resources that you no longer want to use. This way, your account doesn't incur any further charges."}]},{id:"connect-appflow-t17-s28",eyebrow:null,duration:null,title:"Clean up in Amazon S3",blocks:[{type:"p",text:"Because you used an S3 bucket as both a source and a destination throughout this tutorial,"},{type:"p",text:"Amazon S3 hosted multiple files. Unless you delete these files, their storage continues to incur charges on your AWS account. Before you delete an S3 bucket, ensure you have saved any important files to another location."}]},{id:"connect-appflow-t17-s29",eyebrow:null,duration:null,title:"To clean up your S3 bucket",blocks:[{type:"p",text:"1. Open the Amazon S3 console at https://console.aws.amazon.com/s3/."},{type:"p",text:"2. In the Buckets section, select your S3 bucket and choose Empty. Follow the prompts to delete the contents of the bucket."},{type:"p",text:"3. In the Buckets section, select your S3 bucket and choose Delete. Follow the prompts to delete the S3 bucket."},{type:"callout",variant:"warning",title:"Warning",body:["Because S3 bucket names are globally unique, when you delete your S3 bucket,","someone else can use its name. If you want to reserve an S3 bucket name, don't delete the bucket."]}]},{id:"connect-appflow-t17-s30",eyebrow:null,duration:null,title:"Step 5: Clean up",blocks:[{type:"p",text:"Now you have deleted all of the Amazon S3 resources that you created for the tutorial."},{type:"p",text:"For more information on how to empty and delete S3 buckets, see the following resources:"},{type:"ul",items:["Emptying a bucket in the Amazon S3 User Guide.","Deleting a bucket in the Amazon S3 User Guide."]}]},{id:"connect-appflow-t17-s31",eyebrow:null,duration:null,title:"Clean up in Amazon AppFlow",blocks:[{type:"p",text:"Amazon AppFlow stores both your connection and flows. To clean up all resources that you created in this tutorial, delete the two flows and your connection to the SaaS application."}]},{id:"connect-appflow-t17-s32",eyebrow:null,duration:null,title:"To clean up your flows",blocks:[{type:"p",text:"1. Open the Amazon AppFlow console at https://console.aws.amazon.com/appflow/."},{type:"p",text:"2. In the Flows section, select a flow and choose Delete. Follow the prompts to delete your flow."},{type:"p",text:"3. Perform the above step for any flows that remain."}]},{id:"connect-appflow-t17-s33",eyebrow:null,duration:null,title:"To clean up your connection",blocks:[{type:"p",text:"1. Open the Amazon AppFlow console at https://console.aws.amazon.com/appflow/."},{type:"p",text:"2. In the Connections section, under Connectors, open the Choose a connector box. Select the connector that you used in the tutorial."},{type:"p",text:"3. Select the connection and choose Delete."},{type:"p",text:"4. If you used more than one connector, repeat steps 2 and 3 for all connectors."},{type:"p",text:"Now you have deleted all of the resources that you created within Amazon AppFlow for the tutorial."}]},{id:"connect-appflow-t17-s34",eyebrow:null,duration:null,title:"Clean up in Salesforce",blocks:[{type:"p",text:"If you used Salesforce for this tutorial and uploaded the sample data from an S3 bucket to"},{type:"p",text:"Salesforce, you might want to delete the sample account records."}]},{id:"connect-appflow-t17-s35",eyebrow:null,duration:null,title:"To delete imported records in Salesforce",blocks:[{type:"p",text:"Follow the directions in"},{type:"p",text:"Mass delete records."}]},{id:"connect-appflow-t17-s36",eyebrow:null,duration:null,title:"Clean up in Amazon AppFlow",blocks:[{type:"p",text:"After you complete these steps, you have cleaned up all of the resources that you created in this tutorial. Deleted resources no longer incur charges on your AWS account."}]}],reviewQuestions:[]}],quiz:null};export{e as course};
